\begin{document}

\section*{Minimal Single-Medium SAT Lagrangian (Readable Form)}

\paragraph{Fields and symmetries.}
Tetrad $e^{a}{}_{\mu}$ (with metric $g_{\mu\nu}=\eta_{ab} e^{a}{}_{\mu} e^{b}{}_{\nu}$, determinant $e\equiv\det(e^{a}{}_{\mu})=\sqrt{-g}$); 
unit timelike time-flow field $u^{\mu}$; compact phase $\theta\sim\theta+2\pi$.
Diffeomorphism invariance, local Lorentz invariance in the tetrad frame, and $\theta$-shift symmetry 
(broken only by a periodic potential).

\paragraph{Action.} The minimal SAT action is
\begin{equation}
S_{\min}=\int d^4x\, e\, \mathcal{L}_{\min},
\end{equation}
with Lagrangian density
\begin{align}
\mathcal{L}_{\min}
&= \frac{M_P^2}{2}\,T(e)
\;+\; \lambda\,(u^{\mu}u_{\mu}+1) \nonumber\\[3pt]
&\quad + \frac{\rho}{2}\,(\nabla_{\mu}u_{\nu})(\nabla^{\mu}u^{\nu})
\;+\; \frac{f^2}{2}\, g^{\mu\nu}\,\partial_{\mu}\theta\,\partial_{\nu}\theta
\;-\; \mu^4\,(1-\cos\theta) \nonumber\\[3pt]
&\quad + \frac{\alpha_1}{M_*^2}\, \big[(\nabla_{\mu}u_{\nu})(\nabla^{\mu}u^{\nu})\big]\,
\big(g^{\rho\sigma}\partial_{\rho}\theta\,\partial_{\sigma}\theta\big)
\;+\; \frac{\alpha_2}{M_*^2}\, (\nabla_{\mu}u_{\nu})\,\partial^{\mu}\theta\,\partial^{\nu}\theta \nonumber\\[3pt]
&\quad + \frac{\beta}{M_*^2}\, \big(g^{\mu\nu}\partial_{\mu}\theta\,\partial_{\nu}\theta\big)^2,
\label{eq:Lmin}
\end{align}
where $M_P$ is the (reduced) Planck scale, $M_*$ a high elastic cutoff scale, $\rho>0$ an elastic modulus, 
$f$ the compact-field stiffness, $\mu$ the periodic scale, and $\alpha_{1,2},\beta$ are small, 
dimensionless elastic constants.
The Lagrange multiplier $\lambda$ enforces the unit-timelike constraint $u^{\mu}u_{\mu}=-1$.

\paragraph{TEGR (gravity) sector.}
The torsion scalar of teleparallel gravity is
\begin{equation}
T(e) \;=\; \frac{1}{4} T^{\rho}{}_{\mu\nu}T_{\rho}{}^{\mu\nu}
+ \frac{1}{2} T^{\rho}{}_{\mu\nu}T^{\nu\mu}{}_{\rho}
- T_{\rho} T^{\rho},
\qquad
T^{\rho}{}_{\mu\nu} \equiv e_{a}{}^{\rho}\,(\partial_{\mu}e^{a}{}_{\nu}-\partial_{\nu}e^{a}{}_{\mu}),
\quad
T_{\rho}\equiv T^{\mu}{}_{\mu\rho}.
\end{equation}
This reproduces GR at leading order (TEGR equivalence).

\paragraph{Optional kinematic decomposition of the $u^{\mu}$-strain.}
One may replace $(\nabla u)^2\equiv (\nabla_{\mu}u_{\nu})(\nabla^{\mu}u^{\nu})$ by the standard 
expansion/shear/vorticity scalars:
\begin{align}
\theta_{\!u} &\equiv \nabla_{\mu}u^{\mu},\qquad
\sigma_{\mu\nu} \equiv \frac{1}{2}(\nabla_{\mu}u_{\nu}+\nabla_{\nu}u_{\mu}) - \frac{1}{3}\,\theta_{\!u}\,g_{\mu\nu},\qquad
\omega_{\mu\nu} \equiv \frac{1}{2}(\nabla_{\mu}u_{\nu}-\nabla_{\nu}u_{\mu}),\\
(\nabla u)^2 &= c_\theta\,\theta_{\!u}^{2} + c_\sigma\,\sigma_{\mu\nu}\sigma^{\mu\nu} + c_\omega\,\omega_{\mu\nu}\omega^{\mu\nu},
\end{align}
with positive $(c_\theta,c_\sigma,c_\omega)$ to avoid ghosts/gradient instabilities.  This is equivalent up to redefinitions of $\rho,\alpha_{1,2}$.

\paragraph{Compact field sector and kinks.}
The periodic potential $V(\theta)=\mu^4(1-\cos\theta)$ supports topological defects (kinks/domain walls).
The small-oscillation mass is $m_\theta=\mu^2/f$, and the $1$D kink energy is $E_{\rm kink}\approx 8 f^2 m_\theta$ (sine-Gordon estimate).

\paragraph{Holonomy \& quantization (topological data of solutions).}
Compactness implies integer winding
$N=\frac{1}{2\pi}\oint d\theta\in\mathbb{Z}$,
and gauge/spin holonomies are captured by Wilson loops
$\mathcal{W}[C]=\mathrm{Tr}\,\mathcal{P}\exp\oint_C A$.
These integers/classes discretize sectors (charges, spin, allowed bound states)
without adding extra terms to $\mathcal{L}_{\min}$.

\paragraph{Optional parity tag (not part of $\mathcal{L}_{\min}$).}
