\paragraph{Fields.} Metric $g_{\mu\nu}$, unit timelike flow $u^\mu$ with constraint $u^\mu u_\mu=-1$, and compact phase $\theta\sim\theta+2\pi$.

\paragraph{Minimal Lagrangian (Einstein--Hilbert form).}
\begin{align}
\mathcal L_{\min}
&= \frac{M_P^2}{2}\,R
+ \lambda\,(u^\mu u_\mu+1)
+ \frac{\rho}{2}\,(\nabla_\mu u_\nu)(\nabla^\mu u^\nu)
+ \frac{f^2}{2}\,\partial_\mu\theta\,\partial^\mu\theta
- \mu^4(1-\cos\theta)\nonumber\\
&\qquad
+ \frac{\alpha_1}{M_*^2}\,[(\nabla u)^2]\,(\partial\theta)^2
+ \frac{\alpha_2}{M_*^2}\,(\nabla_\mu u_\nu)\,\partial^\mu\theta\,\partial^\nu\theta
+ \frac{\beta}{M_*^2}\,[(\partial\theta)^2]^2,
\label{eq:L}
\end{align}
with $(\nabla u)^2\equiv (\nabla_\mu u_\nu)(\nabla^\mu u^\nu)$ and $(\partial\theta)^2\equiv g^{\mu\nu}\partial_\mu\theta\,\partial_\nu\theta$.

\subsection*{1. Euler--Lagrange for $\theta$}

\noindent The equation of motion is $\partial_\theta\mathcal L - \nabla_\mu(\partial \mathcal L/\partial(\partial_\mu\theta))=0$.
\begin{align}
\frac{\partial \mathcal L}{\partial \theta} &= -\mu^4 \sin\theta,\\[4pt]
\frac{\partial \mathcal L}{\partial (\partial_\mu\theta)} 
&= f^2\,\partial^\mu\theta
+ \frac{2\alpha_1}{M_*^2}\,(\nabla u)^2\,\partial^\mu\theta
+ \frac{\alpha_2}{M_*^2}\,(\nabla^\mu u_\nu + \nabla_\nu u^\mu)\,\partial^\nu\theta
+ \frac{4\beta}{M_*^2}\,(\partial\theta)^2\,\partial^\mu\theta.
\end{align}
Thus
\begin{align}
\boxed{\;
\nabla_\mu\!\left[
f^2\,\partial^\mu\theta
+ \frac{2\alpha_1}{M_*^2}(\nabla u)^2\,\partial^\mu\theta
+ \frac{\alpha_2}{M_*^2}(\nabla^\mu u_\nu+\nabla_\nu u^\mu)\,\partial^\nu\theta
+ \frac{4\beta}{M_*^2}(\partial\theta)^2\,\partial^\mu\theta
\right]
+ \mu^4 \sin\theta = 0\; .}
\label{eq:EOM-theta}
\end{align}

\subsection*{2. Euler--Lagrange for $u_\nu$}

\noindent Varying $\nabla_\mu u_\nu \mapsto \nabla_\mu u_\nu + \nabla_\mu \delta u_\nu$ and integrating by parts,
\begin{align}
\frac{\partial \mathcal L}{\partial(\nabla_\mu u_\nu)} 
&= \rho\,\nabla^\mu u^\nu
+ \frac{2\alpha_1}{M_*^2}\,(\partial\theta)^2\,\nabla^\mu u^\nu
+ \frac{\alpha_2}{M_*^2}\,\partial^\mu\theta\,\partial^\nu\theta,\\
\frac{\partial \mathcal L}{\partial u_\nu} &= 2\lambda\,u^\nu .
\end{align}
Hence
\begin{align}
\boxed{\;
-\,\nabla_\mu\!\left[\rho\,\nabla^\mu u^\nu
+ \frac{2\alpha_1}{M_*^2}\,(\partial\theta)^2\,\nabla^\mu u^\nu
+ \frac{\alpha_2}{M_*^2}\,\partial^\mu\theta\,\partial^\nu\theta\right]
+ 2\lambda\,u^\nu = 0\; .}
\label{eq:EOM-u}
\end{align}
The Lagrange multiplier enforces the unit constraint:
\begin{align}
\boxed{\,u^\mu u_\mu = -1\, ,}\qquad
\text{and}\qquad
u_\nu \eqref{eq:EOM-u}\ \Rightarrow\ \lambda = \frac{1}{2}\,u_\nu \nabla_\mu\!\left[\cdots\right].
\end{align}

\subsection*{3. Metric variation (Einstein equations)}

\noindent Varying $g^{\mu\nu}$ gives
\begin{align}
\boxed{\; M_P^2\,G_{\mu\nu} = T_{\mu\nu}\; ,}
\end{align}
with total stress tensor $T_{\mu\nu}=-\frac{2}{\sqrt{-g}}\frac{\delta S_\text{matter}}{\delta g^{\mu\nu}}$ from the non-gravitational pieces in \eqref{eq:L}.
Splitting by sectors:
\begin{align}
T_{\mu\nu}^{(\theta)}
&= f^2\,\partial_\mu\theta\,\partial_\nu\theta
- g_{\mu\nu}\!\left(\frac{f^2}{2}(\partial\theta)^2 - \mu^4(1-\cos\theta)\right),\\
T_{\mu\nu}^{(u)}
&= \rho\,\nabla_\mu u_\alpha\,\nabla_\nu u^\alpha - \frac{\rho}{2}\,g_{\mu\nu}\,(\nabla u)^2
+ 2\lambda\,u_\mu u_\nu ,\\
T_{\mu\nu}^{(\alpha_1)}
&= \frac{\alpha_1}{M_*^2}\Big\{
2(\partial\theta)^2\,\nabla_\mu u_\alpha\,\nabla_\nu u^\alpha
- g_{\mu\nu}\,[(\nabla u)^2]\,(\partial\theta)^2
\Big\},\\
T_{\mu\nu}^{(\alpha_2)}
&= \frac{\alpha_2}{M_*^2}\Big\{
(\partial_\mu\theta\,\partial^\beta\theta)\,\nabla_\nu u_\beta
+ (\partial_\nu\theta\,\partial^\beta\theta)\,\nabla_\mu u_\beta
- g_{\mu\nu}\,(\nabla_\alpha u_\beta)\,\partial^\alpha\theta\,\partial^\beta\theta
\Big\},\\
T_{\mu\nu}^{(\beta)}
&= \frac{\beta}{M_*^2}\Big\{
4(\partial\theta)^2\,\partial_\mu\theta\,\partial_\nu\theta
- g_{\mu\nu}\,[(\partial\theta)^2]^2
\Big\}.
\end{align}
On-shell diffeomorphism invariance gives $\nabla_\mu T^{\mu\nu}=0$.

\subsection*{4. Noether currents}

\paragraph{(i) $\theta$-shift (internal) symmetry.} 
For constant $\delta\theta=\epsilon$, the Noether current is
\begin{align}
J^\mu_{\theta}
&= \frac{\partial \mathcal L}{\partial (\partial_\mu\theta)}\,\delta\theta
= \epsilon\Big[
f^2\,\partial^\mu\theta
+ \frac{2\alpha_1}{M_*^2}(\nabla u)^2\,\partial^\mu\theta
+ \frac{\alpha_2}{M_*^2}(\nabla^\mu u_\nu+\nabla_\nu u^\mu)\,\partial^\nu\theta
+ \frac{4\beta}{M_*^2}(\partial\theta)^2\,\partial^\mu\theta\Big].
\end{align}
Its divergence is
\begin{align}
\nabla_\mu J^\mu_{\theta}
= \epsilon\,\mu^4 \sin\theta \,,
\end{align}
so the current is strictly conserved only when the periodic potential is absent (or to the extent that its effects average to zero modulo $2\pi$).

\paragraph{(ii) Spacetime symmetries.}
Diffeomorphism invariance yields the covariantly conserved stress tensor above, $\nabla_\mu T^{\mu\nu}=0$. Local Lorentz symmetry (tetrad frame) leads to the antisymmetric part of the spin/hyper-momentum tensor vanishing on-shell.

\bigskip
\noindent\textbf{FRW specialization (ready to integrate).}
For $ds^2=-dt^2+a(t)^2 d\mathbf x^2$, $u^\mu=(1,0,0,0)$, the $\theta$ equation reduces to
\begin{align}
\ddot\theta + 3H\dot\theta - \frac{1}{a^2}\nabla^2\theta
+ \frac{\mu^4}{f^2}\sin\theta
+ \frac{2\alpha_1}{M_*^2 f^2}\,\partial_t\!\Big[a^{-3}(\nabla u)^2\,a^{3}\dot\theta\Big]
+ \frac{\alpha_2}{M_*^2 f^2}\,\nabla_\mu\!\Big[(\nabla^\mu u_\nu+\nabla_\nu u^\mu)\,\partial^\nu\theta\Big]
+ \frac{4\beta}{M_*^2 f^2}\,\nabla_\mu\!\Big[(\partial\theta)^2\,\partial^\mu\theta\Big]
= 0.
\end{align}
Set $\alpha_{1,2},\beta\to0$ for the minimal background, then re-insert to study intrinsic pumping and kink nucleation.

\end{document}
""")

