from textwrap import dedent

tex = dedent(r"""
\documentclass[11pt]{article}
\usepackage[a4paper,margin=1in]{geometry}
\usepackage{amsmath,amssymb,mathtools,physics,bm}
\usepackage{microtype}
\begin{document}

\section*{Holonomy-Generated QM Sector (Minimal SAT Quantization)}

\subsection*{Kinematics (single medium)}
Fields: metric/tetrad $g_{\mu\nu}$, unit time-flow $u^\mu$ with constraint $u^\mu u_\mu=-1$, compact phase $\theta\sim\theta+2\pi$.
Minimal Lagrangian $\mathcal L_{\min}$ as in the main sheet (Einstein--Hilbert form). For the kinematic quantization we treat $g_{\mu\nu},u^\mu$ as fixed background (semiclassical) and quantize $(\theta,\pi_\theta)$ and their holonomies/fluxes.

\paragraph{Canonical variables.}
With $e=\sqrt{-g}$, the canonical momentum is $\pi_\theta = \partial\mathcal L/\partial(\partial_0\theta) = e\,f^2\,g^{0\nu}\partial_\nu\theta$.
Equal-time Poisson bracket: $\{\theta(t,\mathbf x),\pi_\theta(t,\mathbf y)\}=\delta^{(3)}(\mathbf x-\mathbf y)$.
Quantization: $[\hat\theta(\mathbf x),\hat\pi_\theta(\mathbf y)]= i\hbar_{\rm eff}\,\delta^{(3)}(\mathbf x-\mathbf y)$,
with $\hbar_{\rm eff}$ an emergent scale fixed by the medium's microphysics (kept explicit).

\subsection*{Holonomy and flux operators}
Let $C$ be a closed loop and $\Sigma$ an oriented surface.
Define the \emph{phase holonomy} and the \emph{momentum flux}
\begin{align}
\hat{U}[C] &\equiv \exp\!\Big(i\oint_C d\hat\theta\Big) = \exp\!\Big(i\int_C \partial_i\hat\theta\,dx^i\Big),\\
\hat\Pi[\Sigma] &\equiv \int_\Sigma \hat\pi_\theta\, n_i\, d\Sigma^i \qquad (n_i \text{ unit normal on } \Sigma).
\end{align}
For smooth configurations without defects, $\oint_C d\theta=0$. In the presence of $\theta$-defects (kinks/domain walls/strings), holonomy detects the integer winding number
$N(C)=\frac{1}{2\pi}\oint_C d\theta\in\mathbb Z$.
The fundamental loop--flux algebra follows from the canonical commutator and Stokes' theorem:
\begin{equation}
\boxed{\;\hat U[C]\;\hat\Pi[\Sigma]\;=\; \exp\!\big(i\,\hbar_{\rm eff}\,I(C,\Sigma)\big)\;\hat\Pi[\Sigma]\;\hat U[C]\; ,\;}
\end{equation}
where $I(C,\Sigma)\in\mathbb Z$ is the oriented intersection number between $C$ and $\Sigma$.
This is the minimal holonomy-generated quantization: discreteness enters via integer topological data.

\subsection*{Hilbert space (kinematical and physical)}
Choose a finite 3-volume with a cellular decomposition $(\{\Sigma_a\},\{C_b\})$ such that any loop/surface is integer-combinable from the basis. The \emph{kinematical} Hilbert space is the direct sum over topological sectors
\begin{equation}
\mathcal H_{\rm kin} \;=\; \bigoplus_{\bm N\in\mathbb Z^{b_1}} \mathcal H_{\bm N}, \qquad
\hat U[C_b]\ket{\bm N,\psi} = e^{\,i\,2\pi N_b}\ket{\bm N,\psi},
\end{equation}
with $b_1$ the first Betti number (number of independent non-contractible loops).
Within a fixed sector $\bm N$ the states are square-integrable wavefunctionals $\psi[\theta]$ (periodic in $\theta$) or, equivalently, functionals of $\{\Pi[\Sigma_a]\}$ in the holonomy representation (GNS construction of the loop--flux algebra).
The \emph{physical} Hilbert space is obtained by imposing the constraints: (i) the $u^\mu$-unit constraint (already solved at the background level), and (ii) diffeomorphism invariance (group averaging), yielding diffeo-invariant classes of loop/flux states.

\subsection*{Minimal Hamiltonian and spectrum}
On a fixed FRW background $ds^2=-dt^2+a^2 d\mathbf x^2$ with comoving $u^\mu=(1,0,0,0)$, the compact field Hamiltonian is
\begin{equation}
\hat{\mathcal H}_\theta
= \int d^3x \left[ \frac{\hat\pi_\theta^2}{2 a^3 f^2} + \frac{a f^2}{2}\,(\nabla\hat\theta)^2 + a^3\,\mu^4\,(1-\cos\hat\theta) \right].
\end{equation}
Small oscillations (no defects) give a bosonic spectrum with dispersion $\omega_k^2 = k^2 + m_\theta^2$ (physical $k/a$), $m_\theta=\mu^2/f$.
Topological sectors add solitonic bands: a single kink has quantum zero-mode (center-of-mass) and small-shape excitations; multi-kink sectors are labeled by integer winding data and their braid/linking.

\subsection*{Holonomy-driven quantization rules}
\begin{itemize}
\item \textbf{Topological charge:} $\hat N[C] \equiv \tfrac{1}{2\pi}\oint_C d\hat\theta$ has integer spectrum.
\item \textbf{Bohr--Sommerfeld (action holonomy):} for a bound orbit $\gamma$ of a collective coordinate $q$, $\oint_\gamma p\,dq = 2\pi n\,\hbar_{\rm eff}$ (semiclassical levels).
\item \textbf{Berry/holonomy phases:} adiabatic transport of a defect state around a loop in configuration space yields a geometric phase determined by the loop--flux algebra above (spin/statistics tags).
\end{itemize}

\subsection*{Path integral (sum over sectors)}
The quantum theory is equivalently defined by
\begin{equation}
\mathcal Z \;=\; \sum_{[N]}\; \int\mathcal D\theta_{[N]}\,\exp\!\left\{ \frac{i}{\hbar_{\rm eff}}\int d^4x\sqrt{-g}\,\mathcal L_{\min}(\theta,u,g)\right\},
\end{equation}
a sum over topological sectors $[N]$ (inequivalent boundary conditions / defect content). Coupling to long-wavelength $u$-strain via the intrinsic elastic terms produces mode conversion (pumping) within the same single medium.

\subsection*{Observables (minimal set)}
\begin{align}
&\text{Local: } \hat\theta(x),\ \hat\pi_\theta(x);\qquad
\text{Two-point: }\ \langle \hat\theta(x)\hat\theta(y)\rangle;\qquad
\text{Energy: }\ \hat H_\theta.\\
&\text{Topological: } \hat U[C],\ \hat\Pi[\Sigma],\ \hat N[C];\qquad
\text{Defect creation: } \hat K[\gamma]\ \text{(raises linking/winding)}.\\
&\text{Holonomy fingerprints: } \text{integer phase steps, Berry phases under adiabatic loops.}
\end{align}

\subsection*{Consistency \& limits}
\begin{itemize}
\item \emph{IR/GR limit:} with $\mu\to0$ and no defects, $\theta$ reduces to a free compact scalar; gravity remains GR at leading order.
\item \emph{UV/elastic control:} no higher-time derivatives; $\alpha_{1,2},\beta$ small preserve stability and causality; $\hbar_{\rm eff}$ remains an external medium constant to be fixed by matching.
\item \emph{Diffeomorphism invariance:} physical states are diffeo-equivalence classes of loop/flux data; $\nabla_\mu T^{\mu\nu}=0$ holds on-shell.
\end{itemize}

\subsection*{Minimal predictions (holonomy-driven)}
(i) Quantized, \emph{achromatic} phase steps along lines crossing topological sheets (integer ratios across sightlines).  
(ii) Loop--flux uncertainty: $\Delta N\,\Delta\Pi \gtrsim \frac{1}{2}|I(C,\Sigma)|\,\hbar_{\rm eff}$.  
(iii) Defect band structure: discrete zero-mode ladders for kink composites; absence of stable high-$n$ exotics consistent with holonomy classes.

\end{document}
""")

path = "/mnt/data/SAT_QM_min_holonomy.tex"
with open(path, "w") as f:
    f.write(tex)

path

